import type { Coordinate } from "@/lib/tolls";

const REQUEST_TIMEOUT_MS = 8_000;
const RETRY_DELAY_MS = 300;

type TraceEdge = {
  toll?: boolean;
  way_id?: string | number;
  names?: string[];
  begin_shape_index?: number;
  end_shape_index?: number;
  end_node?: {
    type?: string;
    node_id?: string | number;
  };
};

type LocalTraceResult =
  | { ok: true; edges: TraceEdge[] }
  | { ok: false; message: string };

function delay(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function retryableStatus(status: number) {
  return status === 429 || status === 500 || status === 502 || status === 503 || status === 504;
}

export async function localTrace(window: Coordinate[], deadlineAt: number): Promise<LocalTraceResult> {
  if (window.length < 2) return { ok: false, message: "Недостаточно точек в локальном окне" };
  const shape = window.map(([lon, lat]) => ({ lat, lon }));
  let lastMessage = "Локальный map matching не выполнен";

  for (let attempt = 1; attempt <= 2; attempt += 1) {
    const remainingMs = deadlineAt - Date.now();
    if (remainingMs < 800) return { ok: false, message: "Исчерпан общий бюджет локальной проверки" };
    const timeoutMs = Math.max(700, Math.min(REQUEST_TIMEOUT_MS, remainingMs - 100));

    try {
      const response = await fetch("https://valhalla1.openstreetmap.de/trace_attributes", {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          "User-Agent": "MezhgorodCalc/2.0",
        },
        body: JSON.stringify({
          shape,
          costing: "auto",
          shape_match: "walk_or_snap",
          trace_options: {
            search_radius: 45,
            gps_accuracy: 8,
            breakage_distance: 1500,
            interpolation_distance: 50,
          },
          filters: {
            action: "include",
            attributes: [
              "edge.toll",
              "edge.way_id",
              "edge.names",
              "edge.begin_shape_index",
              "edge.end_shape_index",
              "edge.end_osm_node_id",
              "node.type",
            ],
          },
        }),
        signal: AbortSignal.timeout(timeoutMs),
      });

      if (response.ok) {
        const data = (await response.json()) as { edges?: TraceEdge[] };
        const edges = Array.isArray(data.edges) ? data.edges : [];
        return edges.length > 0
          ? { ok: true, edges }
          : { ok: false, message: "Valhalla не вернула дорожные рёбра локального окна" };
      }

      const details = await response.text().catch(() => "");
      lastMessage = `HTTP ${response.status}${details ? ` — ${details.slice(0, 100)}` : ""}`;
      if (!retryableStatus(response.status)) return { ok: false, message: lastMessage };
    } catch (error) {
      lastMessage = error instanceof Error ? error.message : "неизвестная ошибка map matching";
    }

    if (attempt < 2) {
      const remainingAfterAttempt = deadlineAt - Date.now();
      if (remainingAfterAttempt <= RETRY_DELAY_MS + 800) break;
      await delay(RETRY_DELAY_MS);
    }
  }

  return { ok: false, message: lastMessage };
}

import type { Coordinate } from "@/lib/tolls";
import type { TollBoothEvent } from "@/lib/toll-validator";
import type { M4PlazaNodeGroup } from "@/lib/toll-engine/m4-plaza-nodes";
import { localTrace } from "@/lib/toll-engine/m4-local-trace";
import { candidatesForRoute, CANDIDATE_RADIUS_KM, WINDOW_HALF_KM, type Candidate } from "@/lib/toll-engine/m4-route-candidates";
import { classifyM4TraversalWithoutTollEdge, matchM4TollBoothEdges, type M4TraceEdge } from "@/lib/toll-engine/m4-toll-booth-evidence";

const VALIDATION_BUDGET_MS = 55_000;
const CONCURRENCY = 2;

export type M4LocalPlazaCheck = {
  km: number;
  routeProgressMeters?: number;
  model: M4PlazaNodeGroup["model"];
  status: "confirmed" | "rejected" | "unknown";
  evidence: "map_matching" | "route_traversal" | "none";
  nearestDistanceKm: number;
  matchedNodeIds: string[];
  expectedNodeIds: string[];
  windowPointCount: number;
  message: string;
};

export type M4RoutePlazaValidation = {
  source: "Valhalla local PVP map matching + strict route traversal fallback";
  candidateRadiusKm: number;
  windowHalfKm: number;
  candidateCount: number;
  routeDistanceMeters: number;
  routeDurationSeconds?: number;
  checkedCandidateCount: number;
  confirmedCount: number;
  rejectedCount: number;
  unknownCount: number;
  complete: boolean;
  events: TollBoothEvent[];
  checks: M4LocalPlazaCheck[];
  elapsedMs: number;
  message: string;
};



function unavailableResult(candidate: Candidate, remoteMessage: string): { check: M4LocalPlazaCheck; events: TollBoothEvent[] } {
  const nearestDistanceKm = Math.round(candidate.nearestDistanceKm * 1000) / 1000;
  const traversalFallbackStatus = classifyM4TraversalWithoutTollEdge(candidate.traversal.reason);
  if (candidate.traversal.confirmed) {
    return {
      check: {
        km: candidate.plaza.km,
        model: candidate.plaza.model,
        status: "unknown",
        evidence: "route_traversal",
        nearestDistanceKm,
        matchedNodeIds: [],
        expectedNodeIds: [...candidate.plaza.nodeIds],
        windowPointCount: candidate.window.length,
        message: `Удалённый map matching недоступен (${remoteMessage}); маршрут проходит рядом с OSM-якорем ПВП на ${Math.round(candidate.traversal.nearestDistanceKm * 1000)} м, но геометрия не доказывает пересечение платного ребра (возможен бесплатный съезд/объезд). Тариф не начислен.`,
      },
      events: [],
    };
  }

  // The 1.5-km candidate radius is deliberately wider than the strict
  // physical crossing radius. If remote map matching is unavailable and the
  // route itself stays outside the strict 200-metre radius of every saved
  // toll-booth anchor, this is positive evidence of a near miss, not an
  // unresolved traversal. Keeping these as unknown makes long M-4 routes fail
  // closed merely because they pass near an alternative plaza or ramp.
  if (traversalFallbackStatus === "rejected") {
    return {
      check: {
        km: candidate.plaza.km,
        model: candidate.plaza.model,
        status: "rejected",
        evidence: "route_traversal",
        nearestDistanceKm,
        matchedNodeIds: [],
        expectedNodeIds: [...candidate.plaza.nodeIds],
        windowPointCount: candidate.window.length,
        message: `Удалённый map matching недоступен (${remoteMessage}); кандидат отклонён геометрией: маршрут проходит в ${Math.round(candidate.traversal.nearestDistanceKm * 1000)} м от ближайшего сохранённого OSM-якоря ПВП, то есть вне строгого радиуса пересечения.`,
      },
      events: [],
    };
  }

  return {
    check: {
      km: candidate.plaza.km,
      model: candidate.plaza.model,
      status: "unknown",
      evidence: "none",
      nearestDistanceKm,
      matchedNodeIds: [],
      expectedNodeIds: [...candidate.plaza.nodeIds],
      windowPointCount: candidate.window.length,
      message: `${remoteMessage}; строгий route-traversal fallback не подтверждён (${candidate.traversal.reason}).`,
    },
    events: [],
  };
}

async function validateCandidate(candidate: Candidate, deadlineAt: number): Promise<{ check: M4LocalPlazaCheck; events: TollBoothEvent[] }> {
  // The same strict near-miss proof already used after network failure can
  // reject off-route alternative booths before spending a remote request.
  if (!candidate.traversal.confirmed && classifyM4TraversalWithoutTollEdge(candidate.traversal.reason) === "rejected") {
    const result = unavailableResult(candidate, "Запрос не требуется: строгая геометрия исключает сохранённые якоря");
    result.check.message = `Кандидат отклонён строгой геометрией: вне радиуса всех сохранённых OSM-якорей (${Math.round(candidate.traversal.nearestDistanceKm * 1000)} м).`;
    return result;
  }
  const expectedNodeIds = new Set(candidate.plaza.nodeIds);
  const traced = await localTrace(candidate.window, deadlineAt);

  if (!traced.ok) return unavailableResult(candidate, traced.message);

  const match = matchM4TollBoothEdges(expectedNodeIds, traced.edges as M4TraceEdge[]);
  const { events, matchedNodeIds } = match;
  const confirmed = match.status === "confirmed";
  return {
    check: {
      km: candidate.plaza.km,
      model: candidate.plaza.model,
      status: match.status,
      evidence: "map_matching",
      nearestDistanceKm: Math.round(candidate.nearestDistanceKm * 1000) / 1000,
      matchedNodeIds,
      expectedNodeIds: [...expectedNodeIds],
      windowPointCount: candidate.window.length,
      message: confirmed
        ? `Подтверждён конкретный OSM toll-booth node: ${matchedNodeIds.join(", ")}`
        : match.status === "rejected" && matchedNodeIds.length > 0
          ? `OSM toll-booth node найден (${matchedNodeIds.join(", ")}), но Valhalla подтверждает бесплатное ребро; проезд по съезду/объезду не тарифицируется.`
          : match.status === "rejected"
            ? "Успешный map matching не обнаружил ожидаемый OSM toll-booth node; тариф не начислен."
          : "Маршрут приблизился к зоне ПВП, но map matching не подтвердил платное ребро ожидаемого OSM node",
    },
    events,
  };
}

function distanceMeters(a: Coordinate, b: Coordinate) {
  const toRad = Math.PI / 180;
  const dLat = (b[1] - a[1]) * toRad;
  const dLon = (b[0] - a[0]) * toRad;
  const lat1 = a[1] * toRad;
  const lat2 = b[1] * toRad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
  return 6_371_008.8 * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

export async function validateKnownM4Plazas(route: Coordinate[], routeDurationSeconds?: number): Promise<M4RoutePlazaValidation> {
  const startedAt = Date.now();
  const deadlineAt = startedAt + VALIDATION_BUDGET_MS;
  const candidates = candidatesForRoute(route);
  const results: Array<{ check: M4LocalPlazaCheck; events: TollBoothEvent[] }> = new Array(candidates.length);
  let nextIndex = 0;
  async function worker() {
    while (nextIndex < candidates.length) {
      const index = nextIndex++;
      const candidate = candidates[index];
      results[index] = Date.now() >= deadlineAt
        ? unavailableResult(candidate, "Исчерпан общий бюджет локальной проверки")
        : await validateCandidate(candidate, deadlineAt);
    }
  }
  // Start the next candidate when either slot frees up; a single slow PVP
  // must not hold a whole four-request batch and starve all later plazas.
  await Promise.all(Array.from({ length: Math.min(CONCURRENCY, candidates.length) }, worker));

  const routeProgressMeters = new Array<number>(route.length).fill(0);
  for (let index = 1; index < route.length; index += 1) {
    routeProgressMeters[index] = routeProgressMeters[index - 1] + distanceMeters(route[index - 1], route[index]);
  }
  const routeDistanceMeters = routeProgressMeters.at(-1) ?? 0;
  const checks = results.map((item, index) => ({
    ...item.check,
    routeProgressMeters: routeProgressMeters[candidates[index]?.segmentIndex ?? 0],
  }));
  const eventsByNode = new Map<string, TollBoothEvent>();
  for (const item of results) {
    for (const event of item.events) {
      if (event.osmNodeId && !eventsByNode.has(event.osmNodeId)) eventsByNode.set(event.osmNodeId, event);
    }
  }
  const events = [...eventsByNode.values()];
  const confirmedCount = checks.filter((item) => item.status === "confirmed").length;
  const rejectedCount = checks.filter((item) => item.status === "rejected").length;
  const unknownCount = checks.filter((item) => item.status === "unknown").length;
  const traversalCount = checks.filter((item) => item.status === "confirmed" && item.evidence === "route_traversal").length;
  const checkedCandidateCount = confirmedCount + rejectedCount;
  const complete = route.length >= 2 && unknownCount === 0 && checks.length === candidates.length;
  const elapsedMs = Date.now() - startedAt;

  return {
    source: "Valhalla local PVP map matching + strict route traversal fallback",
    candidateRadiusKm: CANDIDATE_RADIUS_KM,
    windowHalfKm: WINDOW_HALF_KM,
    candidateCount: candidates.length,
    routeDistanceMeters,
    ...(Number.isFinite(routeDurationSeconds) && routeDurationSeconds! > 0 ? { routeDurationSeconds } : {}),
    checkedCandidateCount,
    confirmedCount,
    rejectedCount,
    unknownCount,
    complete,
    events,
    checks,
    elapsedMs,
    message: candidates.length === 0
      ? "Геометрия маршрута не входит в 1,5-км зоны известных ПВП М-4."
      : complete
        ? `Проверено ${checkedCandidateCount} локальных кандидатов М-4: подтверждено ${confirmedCount} (из них route-traversal fallback ${traversalCount}), отклонено ${rejectedCount}.`
        : `Локальная проверка неполна: подтверждено ${confirmedCount} (route-traversal fallback ${traversalCount}), отклонено ${rejectedCount}, не проверено ${unknownCount} из ${candidates.length}.`,
  };
}

import core from './quote.cjs';
import {stableTariffWindow} from './tariff-window.mjs';
import {m4TariffPeriodAt} from '../../toll-od-matrix/m4-fare-calendar-2026.mjs';
export function matrixM4Component(production, departureAt, routeSeconds){
 if(production?.exact!==true||!production.tolls)return null;
 // A289 must remain its own separately evidenced component, not disappear in an M4 replacement.
 if(production.tolls.segments?.some(s=>s.startsWith('А-289:')))return null;
 const ids=production.m4PvpPreview?.confirmedPvps;
 if(!Array.isArray(ids)||ids.length<1||new Set(ids).size!==ids.length)return null;
 const unknown=reason=>({tolls:null,reason,priceConfirmation:'unknown'});
 if(!Number.isFinite(routeSeconds)||routeSeconds<0||!Number.isFinite(new Date(departureAt).getTime()))return unknown('m4_crossing_date_missing');
 const window=stableTariffWindow(departureAt,routeSeconds,m4TariffPeriodAt);
 if(window.status!=='resolved')return unknown('m4_'+window.reason);
 const start=window.begin;
 const south=['m4-1046','m4-1093','m4-1184','m4-1223'];
 const positions=ids.map(id=>south.indexOf(id));
 const isSouth=positions.length>1&&positions.every(x=>x>=0)&&positions.every((p,i)=>!i||Math.abs(p-positions[i-1])===1);
 const key=ids.join('>');
 const component={routeId:'selected-fast-route',traversalId:'m4',exactTraversal:true,profileResolved:true,road:isSouth?'m4-south':'m4-candidate',from:isSouth?ids[0].slice(3):key,to:isSouth?ids.at(-1).slice(3):key,profile:start.profile,localDate:start.date};
 const request=c=>({routeId:'selected-fast-route',evidenceComplete:true,components:[c]});
 const actual=core.quote(request(component));
 // Every crossed date must select the same applicable fare/source. A version
 // expiry/change cannot revive a native departure-date fallback.
 if(actual.rub!==null)for(const date of window.dates){
  const day=core.quote(request({...component,localDate:date}));
  if(day.rub!==actual.rub||JSON.stringify(day.components.map(c=>c.source))!==JSON.stringify(actual.components.map(c=>c.source)))return unknown('m4_crossing_fare_version_changes');
 }

 const weekday=core.quote(request({...component,profile:'monThu'})),weekend=core.quote(request({...component,profile:'friSun'}));
 if(actual.rub===null||weekday.rub===null||weekend.rub===null)return null;
 // Source evidence for the full nationwide trip is still incomplete; present replacement as an estimate.
 return {reason:'matrix exact selected-route M4 vector',priceConfirmation:'unconfirmed',tolls:{amount:actual.rub,weekdayAmount:weekday.rub,weekendAmount:weekend.rub,period:start.profile==='monThu'?'понедельник–четверг':'пятница–воскресенье',segments:[`М-4: ${ids.join(' → ')} · Стоимость не подтверждена`],confidence:'matched'}};
}

import core from './quote.cjs';
import {stableTariffWindow} from './tariff-window.mjs';

// These dates are flagged by existing 2026 operator/calendar snapshots. They
// are ambiguity guards, not a borrowed tariff schedule for M11 mainline.
const potentialSpecialDates = new Set(['2026-01-01','2026-01-02','2026-01-03','2026-01-04','2026-01-05','2026-01-06','2026-01-07','2026-01-08','2026-02-23','2026-03-08','2026-03-09','2026-04-30','2026-05-01','2026-05-09','2026-05-10','2026-05-11','2026-06-11','2026-06-12','2026-11-03','2026-11-04','2026-12-30','2026-12-31']);

// The native boundary resolver supplies physical directed OD, independently of
// whether its older partial tariff table contains that cell.
export function matrixM11Component(production, departureAt, routeSeconds) {
  if (production?.boundaryStatus !== 'resolved' || !production.traversal) return null;
  const fail = reason => ({tolls:null, reason});
  if (production.blockedByMixedRoadEvidence) return fail('m11_mixed_paid_road_evidence');
  if(typeof departureAt!=='string'||!/(?:Z|[+-]\d\d:\d\d)$/.test(departureAt))return fail('m11_crossing_time_missing');
  const start = new Date(departureAt);
  if (!Number.isFinite(start.getTime()) || !Number.isFinite(routeSeconds) || routeSeconds < 0) return fail('m11_crossing_date_missing');
  const local = date => ({
    date:new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).format(date),
    day:new Intl.DateTimeFormat('en-US',{timeZone:'Europe/Moscow',weekday:'short'}).format(date),
  });
  const resolve = instant => {
    const p = local(new Date(instant));
    if(!p.date.startsWith('2026-'))return {status:'unknown'};
    const profile=['Fri','Sat','Sun'].includes(p.day)?'friSun':'monThu';
    if(profile==='monThu'&&potentialSpecialDates.has(p.date))return {status:'unknown'};
    return {status:'resolved',date:p.date,profile};
  };
  const window=stableTariffWindow(departureAt,routeSeconds,resolve);
  if(window.status!=='resolved')return fail('m11_'+window.reason);
  const begin=window.begin,profile=begin.profile;
  const {entryPointId:from,exitPointId:to} = production.traversal;
  const component = {routeId:'selected-fast-route',traversalId:'m11',exactTraversal:true,profileResolved:true,road:'m11-58-679',from,to,profile,localDate:begin.date};
  const quote = profile => core.quote({routeId:component.routeId,evidenceComplete:true,components:[{...component,profile}]});
  const actual=quote(profile),weekday=quote('monThu'),weekend=quote('friSun');
  if ([actual,weekday,weekend].some(q=>q.rub===null)) return fail('m11_current_exact_pair_missing');
  for(const date of window.dates){
    const day=core.quote({routeId:component.routeId,evidenceComplete:true,components:[{...component,localDate:date}]});
    if(day.rub!==actual.rub||JSON.stringify(day.components.map(c=>c.source))!==JSON.stringify(actual.components.map(c=>c.source)))return fail('m11_crossing_fare_version_changes');
  }
  return {reason:'matrix dated selected-route M11 direct pair',tolls:{amount:actual.rub,weekdayAmount:weekday.rub,weekendAmount:weekend.rub,period:profile==='monThu'?'понедельник–четверг':'пятница–воскресенье',segments:[`М-11: ${from} → ${to} · Стоимость не подтверждена`],confidence:'matched'}};
}

export function matrixM11GeometryComponent(production) {
  if (production?.exact !== true || !production.parts) return null;
  const parts = production.parts;
  const mainline = matrixM11Component({boundaryStatus:'resolved',traversal:{entryPointId:parts.from,exitPointId:parts.to}},parts.mainlineAt,0);
  if (!mainline?.tolls) return {tolls:null,reason:mainline?.reason ?? 'm11_geometry_pair_missing'};
  if (![parts.headAmount,parts.headWeekday,parts.headWeekend].every(x=>Number.isSafeInteger(x)&&x>=0)) return {tolls:null,reason:'m11_head_amount_invalid'};
  return {reason:'matrix M11 direct mainline pair plus separately proven 15–58 head',tolls:{...mainline.tolls,
    amount:mainline.tolls.amount+parts.headAmount,weekdayAmount:mainline.tolls.weekdayAmount+parts.headWeekday,
    weekendAmount:mainline.tolls.weekendAmount+parts.headWeekend,
    segments:[`М-11 15–58: ${parts.headAmount} ₽ · Стоимость не подтверждена`,...mainline.tolls.segments]}};
}

import type { Coordinate } from "../tolls";
import type { ProductionM4Result, ProductionM4Tolls } from "../toll-engine/m4-production";
import { highwayTariffPeriod } from "../toll-engine/tariff-period";
import { priceA289Route } from "../toll-engine/a289-engine";
import { M4 } from "../toll-data/m4";
import { a289Endpoint, a289ShortRoute } from "./a289-short-route";

const BYPASS = "М-4: Дальний западный обход Краснодара";
type MatrixM4 = {tolls: ProductionM4Tolls | null; reason: string} | null;

/** V3 consumes M4-only production data. A289 and the bypass are independently
 * priced on the same selected geometry and added exactly once. */
export function composeSelectedM4A289(route: Coordinate[], production: ProductionM4Result,
  matrix: MatrixM4, legacySegments: string[], departureAt?: string) {
  const confirmedPvps = production.m4PvpPreview?.confirmedPvps ?? [];
  const hasM4Evidence = confirmedPvps.length > 0;
  const localEndpoints = route.length >= 2 && Boolean(a289Endpoint(route[0]) && a289Endpoint(route.at(-1)!));
  const physical = priceA289Route(route, departureAt);
  const local = a289ShortRoute(route, [], departureAt, hasM4Evidence, false);
  // Nearby M4 diagnostic candidates are not a traversed plaza. Keep local
  // A289 trips usable; a confirmed M4 passage can never be dropped by locality.
  const m4Detected = hasM4Evidence || (!localEndpoints && production.candidate);
  const a289Detected = physical.crossedFrames.length > 0
    || legacySegments.some(name => name.startsWith("А-289:"));
  const bypass = legacySegments.includes(BYPASS) ? M4.find(row => row.name === BYPASS) : null;
  if (!m4Detected && !a289Detected && !bypass) return null;
  const unknown = (reason: string) => ({tolls: null, reason});
  const m4 = matrix ? matrix.tolls : production.tolls;
  if (m4Detected && (!m4 || m4.confidence !== "matched" || (!matrix && !production.exact))) {
    return unknown(`M-4 selected traversal is not completely priced; A-289 cannot replace it: ${matrix?.reason ?? production.reason}`);
  }
  // Reject accidental use of the old mixed production payload instead of
  // subtracting estimated frame prices from an unrelated whole-route tariff.
  if (m4Detected && m4?.segments.some(name => name.startsWith("А-289:"))) {
    return unknown("M-4 input already contains A-289; separate composition required");
  }
  if (a289Detected && !local?.tolls) return unknown(local?.reason ?? "A-289 crossing/exit binding unresolved");
  const values = [...(m4Detected && m4 ? [m4] : []), ...(a289Detected && local?.tolls ? [local.tolls] : [])];
  const period = m4Detected && m4 ? m4.period : physical.period;
  const bypassAmount = highwayTariffPeriod(departureAt).weekend ? bypass?.weekend ?? 0 : bypass?.weekday ?? 0;
  const amount = values.reduce((sum, value) => sum + value.amount, 0) + bypassAmount;
  const weekdayAmount = values.reduce((sum, value) => sum + value.weekdayAmount, 0) + (bypass?.weekday ?? 0);
  const weekendAmount = values.reduce((sum, value) => sum + value.weekendAmount, 0) + (bypass?.weekend ?? 0);
  if (![amount,weekdayAmount,weekendAmount].every(value => Number.isSafeInteger(value) && value >= 0)) return unknown("Invalid M-4/A-289 component amount");
  return {reason:"Selected-route M-4, A-289 and bypass composed as distinct charges",
    tolls:{amount,weekdayAmount,weekendAmount,period,confidence:"matched" as const,
      segments:[...values.flatMap(value => value.segments), ...(bypass ? [`${BYPASS}: ${bypassAmount} ₽ · Стоимость не подтверждена`] : [])]}};
}

import { isUsableRoute } from "./route-candidate";
import { valhalla, osrmRoute, type Located, type RouteWithGeometry } from "../route-providers";
import { SPECIAL_TERRITORY_BOUNDARIES as zones } from "../special-territory-boundaries";
import { analyzeRoute, candidatePlans, findPlanLegStretchAnomaly, followsPlan } from "../special-territory-policy";
import { selectGeographicTerritoryOption } from "../special-territory-options";
import { selectLiveRouteCandidates } from "../route-quality";
