import test from "node:test";
import assert from "node:assert/strict";
import { M4_PLAZA_NODES } from "../lib/toll-engine/m4-plaza-nodes.ts";
import { calculateSpecialOptions } from "../lib/v2-calculation/special-options.ts";

const moscow = { lat: 55.7505412, lng: 37.6174782 };
const donetsk = { lat: 48.0156, lng: 37.8029 };
const routeShape = [
  [donetsk.lng, donetsk.lat],
  ...M4_PLAZA_NODES.filter((plaza) => plaza.km <= 911)
    .sort((a, b) => b.km - a.km)
    .map((plaza) => [plaza.anchors[0].lon, plaza.anchors[0].lat]),
  [moscow.lng, moscow.lat],
];

function encodePolyline(points: number[][]) {
  let previousLat = 0;
  let previousLng = 0;
  let encoded = "";
  const encode = (value: number) => {
    let next = value < 0 ? ~(value << 1) : value << 1;
    let result = "";
    while (next >= 0x20) {
      result += String.fromCharCode((0x20 | (next & 0x1f)) + 63);
      next >>= 5;
    }
    return result + String.fromCharCode(next + 63);
  };
  for (const [lng, lat] of points) {
    const scaledLat = Math.round(lat * 1e6);
    const scaledLng = Math.round(lng * 1e6);
    encoded += encode(scaledLat - previousLat) + encode(scaledLng - previousLng);
    previousLat = scaledLat;
    previousLng = scaledLng;
  }
  return encoded;
}

function distanceKm(point: number[], anchor: { lat: number; lon: number }) {
  return Math.hypot((point[0] - anchor.lon) * 111.32 * Math.cos(anchor.lat * Math.PI / 180), (point[1] - anchor.lat) * 110.574);
}

test("special route toll checks are serialized to avoid saturating Valhalla trace matching", async () => {
  const originalFetch = globalThis.fetch;
  let activeTraces = 0;
  let maxActiveTraces = 0;
  globalThis.fetch = async (input, init) => {
    const url = new URL(String(input));
    if (url.hostname === "valhalla1.openstreetmap.de" && url.pathname === "/route") {
      return new Response(JSON.stringify({
        trip: {
          summary: { length: 1_276.3, time: 63_059 },
          legs: [{ shape: encodePolyline(routeShape), summary: { length: 1_276.3, time: 63_059 }, maneuvers: [] }],
        },
      }), { status: 200, headers: { "Content-Type": "application/json" } });
    }
    if (url.hostname === "router.project-osrm.org") {
      return new Response(JSON.stringify({ routes: [{
        distance: 1_182_600,
        duration: 61_768,
        geometry: { coordinates: routeShape },
        legs: [{ distance: 1_182_600, duration: 61_768, steps: [{ geometry: { coordinates: routeShape } }] }],
      }] }), { status: 200, headers: { "Content-Type": "application/json" } });
    }
    if (url.pathname === "/trace_attributes") {
      activeTraces += 1;
      maxActiveTraces = Math.max(maxActiveTraces, activeTraces);
      await new Promise((resolve) => setTimeout(resolve, 5));
      const request = JSON.parse(String(init?.body ?? "{}"));
      const points = (request.shape ?? []).map((point: { lon: number; lat: number }) => [point.lon, point.lat]);
      const plaza = M4_PLAZA_NODES.map((candidate) => ({
        candidate,
        distance: Math.min(...points.map((point: number[]) => distanceKm(point, candidate.anchors[0]))),
      })).sort((a, b) => a.distance - b.distance)[0]?.candidate;
      activeTraces -= 1;
      return new Response(JSON.stringify({ edges: plaza ? [{
        toll: true,
        way_id: `m4-${plaza.km}`,
        names: ["М-4 Дон"],
        end_node: { type: "toll_booth", node_id: plaza.nodeIds[0] },
      }] : [] }), { status: 200, headers: { "Content-Type": "application/json" } });
    }
    return new Response("{}", { status: 503 });
  };

  try {
    const result = await calculateSpecialOptions(
      { label: "Волноваха — ДНР", position: donetsk },
      { label: "Москва, Россия", position: moscow },
      "2026-10-08T10:00:00+03:00",
    );
    assert.equal(result.options.length, 2, "main and distinct alternative remain available");
    assert.ok(result.options.every((option) => option.fast.tolls.pricingStatus === "priced"));
    assert.ok(result.options.every((option) => (option.fast.tolls.weekdayAmount ?? 0) > 0));
    assert.equal(maxActiveTraces, 2, "only one two-slot M-4 validator runs at a time");
  } finally {
    globalThis.fetch = originalFetch;
  }
});

/** Check every Moscow civil day, not just the endpoints of a trip.
 * Midnight is not a tariff change when profile and applicable source stay the same. */
export function stableTariffWindow(departureAt, routeSeconds, resolve) {
 const fail=reason=>({status:'unknown',reason});
 const beginMs=new Date(departureAt).getTime();
 if(!Number.isFinite(beginMs)||!Number.isFinite(routeSeconds)||routeSeconds<0)return fail('crossing_date_missing');
 const endMs=beginMs+routeSeconds*1000;
 if(!Number.isFinite(new Date(endMs).getTime()))return fail('crossing_date_invalid');
 const begin=resolve(departureAt),end=resolve(new Date(endMs).toISOString());
 if(begin.status!=='resolved'||end.status!=='resolved')return fail('crossing_calendar_unresolved');
 const dates=[];
 const first=new Date(begin.date+'T12:00:00Z').getTime(),last=new Date(end.date+'T12:00:00Z').getTime();
 if(!Number.isFinite(first)||!Number.isFinite(last)||last<first||last-first>366*86400000)return fail('crossing_calendar_unresolved');
 for(let ms=first;ms<=last;ms+=86400000){
  const date=new Date(ms).toISOString().slice(0,10);
  const day=resolve(date+'T12:00:00+03:00');
  if(day.status!=='resolved'||day.profile!==begin.profile)return fail('crossing_profile_changes');
  dates.push(date);
 }
 return {status:'resolved',begin,end,dates};
}

import {deriveStrictM12Span, type M12SpanCoordinate} from './m12-valhalla-span';
import type {M11OsrmLeg} from './m11-road-evidence-types';
const ref = /(?:^|[^0-9A-ZА-Я])(?:M|М)\s*[-‐‑–—]?\s*12(?:[^0-9A-ZА-Я]|$)/iu;
const same = (a:M12SpanCoordinate,b:M12SpanCoordinate) => a[0]===b[0]&&a[1]===b[1];
const normalize = (points:M12SpanCoordinate[]) => points.filter((p,i)=>!i||!same(p,points[i-1]));
/** OSRM step geometry must reproduce the exact selected overview geometry.
 * Destinations are deliberately excluded; disjoint traversals stay unresolved. */
export function deriveM12FromOsrm(legs:M11OsrmLeg[],overview:M12SpanCoordinate[]) {
 const candidate=legs.some(l=>l.steps?.some(s=>ref.test(s.ref?.trim() || s.name || '')));
 const fail=(reason:string)=>({candidate,span:null,reason});
 if(!candidate)return {candidate:false,span:null,reason:null};
 const shape:M12SpanCoordinate[]=[],maneuvers:Array<{street_names:string[];begin_shape_index:number;end_shape_index:number}>=[];
 for(const leg of legs)for(const step of leg.steps??[]){
  const points=step.geometry?.coordinates;
  if(!Array.isArray(points)||!points.length||points.some(p=>p.length!==2||!p.every(Number.isFinite)))return fail('m12_osrm_step_geometry_invalid');
  const coordinates=normalize(points);
  if(shape.length&&!same(shape.at(-1)!,coordinates[0]))return fail('m12_osrm_steps_disconnected');
  const begin=shape.length?shape.length-1:0;
  shape.push(...(shape.length?coordinates.slice(1):coordinates));
  const label=step.ref?.trim() || step.name || '';
  if(ref.test(label))maneuvers.push({street_names:[label],begin_shape_index:begin,end_shape_index:shape.length-1});
 }
 const exact=normalize(overview);
 if(exact.length!==shape.length||shape.some((p,i)=>!same(p,exact[i])))return fail('m12_osrm_overview_not_bound_to_steps');
 const span=deriveStrictM12Span([{coordinates:shape,maneuvers}]);
 return {candidate,span,reason:span?null:'m12_disconnected_or_malformed_strict_span'};
}

